mapper.select:
SELECT sum(leaveCount) AS leaveCount, sum(workOverCount) AS workOverCount, sum(fieldCount) AS fieldCount, ${query.queryType} AS queryType FROM ( SELECT ifnull(COUNT(li.id),0) AS leaveCount, 0 AS workOverCount, 0 AS fieldCount FROM leave_info li LEFT JOIN approval_people ap ON li.approval_now_people_id = ap.id AND li.approval_status = 0
AND ap.user_id = #{query.userId}
GROUP BY li.id UNION SELECT 0 AS leaveCount, ifnull(COUNT(fi.id),0) AS workOverCount, 0 AS fieldCount FROM field_info fi
AND fi.approval_status = 0
AND fi.approval_people_id = #{query.userId}
UNION SELECT 0 AS leaveCount, 0 AS workOverCount, ifnull(COUNT(t.id),0) AS fieldCount FROM work_overtime_info t
AND t.approval_status = 0
AND t.approval_people_id = #{query.userId}
) tmp
